using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;
public static class BableBridgeArt {
 public static string Import(){string path="Assets/Resources/Bable/NewArt/PilgrimBridgeSequence.png";var im=(TextureImporter)AssetImporter.GetAtPath(path);im.textureType=TextureImporterType.Sprite;im.spriteImportMode=SpriteImportMode.Multiple;im.spritePixelsPerUnit=145.12f;im.alphaIsTransparency=true;im.filterMode=FilterMode.Point;im.textureCompression=TextureImporterCompression.Uncompressed;im.maxTextureSize=4096;im.spritesheet=Enumerable.Range(0,16).Select(i=>new SpriteMetaData{name="PilgrimBridge_"+i.ToString("D2"),rect=new Rect(i%8*384,(1-i/8)*480,384,480),alignment=9,pivot=new Vector2(.5f,48f/480)}).ToArray();im.SaveAndReimport();var sprites=AssetDatabase.LoadAllAssetsAtPath(path).OfType<Sprite>().OrderBy(s=>s.name).ToArray();Make("bridgestumble",sprites.Take(2).ToArray(),4);Make("bridgefall",sprites.Skip(2).Take(6).ToArray(),7);Make("bridgeimpact",sprites.Skip(8).Take(4).ToArray(),6);Make("bridgerise",sprites.Skip(12).Take(3).ToArray(),6);AssetDatabase.SaveAssets();return "Four dedicated bridge animation clips imported";}
 static void Make(string action,Sprite[] frames,float fps){string path="Assets/Art/NativeAnimations/Pilgrim_"+action+".anim";var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);if(clip==null){clip=new AnimationClip();AssetDatabase.CreateAsset(clip,path);}clip.frameRate=fps;AnimationUtility.SetObjectReferenceCurve(clip,new EditorCurveBinding{path="",type=typeof(SpriteRenderer),propertyName="m_Sprite"},frames.Select((s,i)=>new ObjectReferenceKeyframe{time=i/fps,value=s}).ToArray());var settings=AnimationUtility.GetAnimationClipSettings(clip);settings.loopTime=false;settings.stopTime=frames.Length/fps;AnimationUtility.SetAnimationClipSettings(clip,settings);var ctl=AssetDatabase.LoadAssetAtPath<AnimatorController>("Assets/Art/NativeAnimations/Pilgrim.controller");var sm=ctl.layers[0].stateMachine;var state=sm.states.Select(c=>c.state).FirstOrDefault(s=>s.name=="right"+action);if(state==null)state=sm.AddState("right"+action);state.motion=clip;EditorUtility.SetDirty(ctl);}
}
